-- Actual synthetic collections/refunds, original source, reservation and crash reconciliation; isolated by rollback.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2070007-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('owner',true,'billing',true,'discount_approved',true))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-m6-007-payment-'||n||'@example.test',now()from generate_series(1,3)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,3)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-m6-006:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,3)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic billing doctor A'),(pg_temp.id(2),'Synthetic billing doctor B');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic price practice A'),(pg_temp.id(22),pg_temp.id(2),'Synthetic price practice B');
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(31),pg_temp.id(21),'Synthetic clinic A','Etc/UTC'),(pg_temp.id(32),pg_temp.id(22),'Synthetic clinic B','Etc/UTC');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(301),pg_temp.id(21),pg_temp.id(3),array['patients.read','appointments.write']);
insert into public.membership_locations(practice_id,membership_id,location_id)values(pg_temp.id(21),pg_temp.id(301),pg_temp.id(31));
insert into public.patient_identities(id)values(pg_temp.id(41)),(pg_temp.id(42));
insert into public.practice_patients(id,practice_id,patient_identity_id,display_name,created_location_id,created_by)values(pg_temp.id(51),pg_temp.id(21),pg_temp.id(41),'Synthetic billing patient A',pg_temp.id(31),pg_temp.id(1)),(pg_temp.id(52),pg_temp.id(22),pg_temp.id(42),'Synthetic billing patient B',pg_temp.id(32),pg_temp.id(2));
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,created_by)values(pg_temp.id(61),pg_temp.id(21),pg_temp.id(1),pg_temp.id(31),pg_temp.id(51),now()+interval'1 day',now()+interval'1 day 20 minutes','Etc/UTC','Synthetic clinic A',pg_temp.id(1)),(pg_temp.id(62),pg_temp.id(22),pg_temp.id(2),pg_temp.id(32),pg_temp.id(52),now()+interval'1 day',now()+interval'1 day 20 minutes','Etc/UTC','Synthetic clinic B',pg_temp.id(2));
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,created_by)values(pg_temp.id(63),pg_temp.id(21),pg_temp.id(1),pg_temp.id(31),pg_temp.id(51),now()+interval'1 day 1 hour',now()+interval'1 day 1 hour 20 minutes','Etc/UTC','Synthetic clinic A',pg_temp.id(1));
set constraints all immediate;set constraints all deferred;
create temporary table results(name text primary key,value jsonb);grant all on results to authenticated;
create function pg_temp.value(k text,field text)returns uuid language sql as $$select(value->>field)::uuid from results where name=k$$;
create function pg_temp.price(service uuid,revision integer,minor text,key integer,currency text default'EGP')returns jsonb language sql security invoker as $$select public.doctor_write_service_price(pg_temp.id(21),pg_temp.id(31),service,revision,'Synthetic visit service',minor,currency,2,pg_temp.id(key))$$;
create function pg_temp.charge(price uuid,quantity integer,key integer,charge uuid default null,revision integer default 0,visit_revision integer default 1)returns jsonb language sql security invoker as $$select public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(61),visit_revision,pg_temp.id(51),price,quantity,charge,revision,'Synthetic attributable charge/correction',pg_temp.id(key))$$;
set local role authenticated;select pg_temp.claim(1);
insert into results values('price1',pg_temp.price(null,0,'29900',701));
insert into results values('charge1',pg_temp.charge(pg_temp.value('price1','id'),5,702));
reset role;
create function pg_temp.payment(kind text,minor text,key integer,original uuid default null,version uuid default null)returns jsonb language sql security invoker as $$select public.doctor_prepare_practice_payment(pg_temp.id(21),pg_temp.id(31),kind,coalesce(version,pg_temp.value('charge1','id')),original,minor,'Synthetic explicit collection/refund',pg_temp.id(key))$$;
create function pg_temp.advance(name text,revision integer,action text,key integer,outcome text default null)returns jsonb language sql security invoker as $$select public.doctor_advance_practice_payment(pg_temp.id(21),pg_temp.id(31),pg_temp.value(name,'id'),revision,action,outcome,pg_temp.id(key))$$;
set local role authenticated;select pg_temp.claim(1);
insert into results values('pending',pg_temp.payment('collection','49900',703));
select is((select value->>'external_transport_enabled'from results where name='pending'),'false','external money transport remains disabled');
select is((select value->>'live_collection'from results where name='pending'),'false','synthetic collection never claims live funds');
select is((select value->>'tax_invoice_available'from results where name='pending'),'false','synthetic receipt is not an approved tax invoice');
select is((select value->>'state'from results where name='pending'),'pending','prepared collection reserves funds without claiming paid state');
select is((select value->'entry'from results where name='pending'),'null'::jsonb,'pending is not a financial receipt');
select is(public.doctor_practice_money_state(pg_temp.id(21),pg_temp.id(31),pg_temp.value('charge1','charge_id'))#>>'{balance,reserved_collection_minor}','49900','pending collection reserves exact charge capacity');
select is(pg_temp.payment('collection','49900',703),(select value from results where name='pending'),'unknown prepare acknowledgement returns original key intent without second reservation');
select throws_ok($$select pg_temp.payment('collection','1',703)$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','same key cannot replace collection amount');
select throws_ok($$select pg_temp.payment('collection','100000',704)$$,'40001','DOCTOR_PRACTICE_OVER_ALLOCATION','second pending intent cannot exceed unreserved balance');
select throws_ok($$select pg_temp.payment('collection','0',705)$$,'22023','DOCTOR_PRACTICE_PAYMENT_INVALID','zero payment cannot produce a receipt');
select throws_ok($$select pg_temp.payment('collection','1.5',706)$$,'22023','DOCTOR_PRACTICE_PAYMENT_INVALID','fractional minor unit is not rounded');
select throws_ok($$select pg_temp.advance('pending',1,'reconcile',707)$$,'40001','DOCTOR_PRACTICE_ACCEPTANCE_EVIDENCE_REQUIRED','reconciliation cannot invent acceptance');
insert into results values('unknown',pg_temp.advance('pending',1,'dispatch',708,'accepted'));
select is((select value->>'state'from results where name='unknown'),'unknown','persisted transport acceptance still requires ledger reconciliation');
select is((select value->'entry'from results where name='unknown'),'null'::jsonb,'accepted transport response is not a posted receipt');
reset role;
select is((select count(*)::integer from doctor_private.synthetic_practice_payment_acceptances),1,'synthetic acceptance persists separately before acknowledgement/ledger posting');
select is((select count(*)::integer from public.doctor_practice_ledger_entries),0,'crash boundary has no invented posted entry');
select is((select count(*)::integer from public.doctor_practice_receipt_counters),0,'transport acceptance does not consume a receipt number');
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.advance('pending',1,'dispatch',708,'accepted'),(select value from results where name='unknown'),'lost dispatch acknowledgement retries exact recorded acceptance result');
select throws_ok($$select pg_temp.advance('pending',2,'dispatch',709,'accepted')$$,'40001','DOCTOR_PRACTICE_RECONCILIATION_REQUIRED','unknown outcome cannot blindly dispatch again under a new key');
select throws_ok($$select pg_temp.advance('pending',2,'cancel',710)$$,'40001','DOCTOR_PRACTICE_RECONCILIATION_REQUIRED','unknown acceptance cannot release reservation by cancellation');
insert into results values('posted',pg_temp.advance('pending',2,'reconcile',711));
select is((select value->>'state'from results where name='posted'),'posted','reconciliation posts only from persisted acceptance');
select is((select value#>>'{entry,amount_minor}'from results where name='posted'),'49900','posted collection is exact and partial');
select is((select value#>>'{entry,receipt_label}'from results where name='posted'),'SYN-00000001','atomic collection issues scoped synthetic receipt');
select is(pg_temp.advance('pending',2,'reconcile',711),(select value from results where name='posted'),'lost posted acknowledgement cannot duplicate collection/receipt');
insert into results values('rejected',pg_temp.payment('collection','20000',712));
select lives_ok($$select pg_temp.advance('rejected',1,'dispatch',713,'rejected')$$,'synthetic failed collection attempt persists outcome evidence');
select is(pg_temp.advance('rejected',2,'reconcile',714)->>'state','failed','rejected transport is failed, never falsely posted');
select is(public.doctor_practice_money_state(pg_temp.id(21),pg_temp.id(31),pg_temp.value('charge1','charge_id'))#>>'{balance,reserved_collection_minor}','0','verified failure releases its reservation');
insert into results values('refundRejected',pg_temp.payment('refund','40000',715,(select(value#>>'{entry,id}')::uuid from results where name='posted')));
select throws_ok($$select pg_temp.payment('refund','10000',716,(select(value#>>'{entry,id}')::uuid from results where name='posted'))$$,'40001','DOCTOR_PRACTICE_OVER_REFUND','concurrent pending refunds reserve original refundable balance');
select lives_ok($$select pg_temp.advance('refundRejected',1,'dispatch',717,'rejected')$$,'rejected refund attempt is separate from ledger settlement');
select is(pg_temp.advance('refundRejected',2,'reconcile',718)->>'state','failed','failed refund has no reversal entry');
insert into results values('refund',pg_temp.payment('refund','30000',719,(select(value#>>'{entry,id}')::uuid from results where name='posted')));
select lives_ok($$select pg_temp.advance('refund',1,'dispatch',720,'accepted')$$,'refund acceptance persists before settlement acknowledgement');
select throws_ok($$select pg_temp.payment('refund','20000',721,(select(value#>>'{entry,id}')::uuid from results where name='posted'))$$,'40001','DOCTOR_PRACTICE_OVER_REFUND','unknown refund retains its original receipt reservation');
insert into results values('reversal',pg_temp.advance('refund',2,'reconcile',722));
select is((select value#>>'{entry,original_entry_id}'from results where name='reversal'),(select value#>>'{entry,id}'from results where name='posted'),'refund reversal links exact original collection');
select is((select value#>>'{entry,receipt_label}'from results where name='reversal'),'SYN-00000002','failed attempts do not consume receipt sequence');
select is(pg_temp.advance('refund',2,'reconcile',722),(select value from results where name='reversal'),'duplicate refund request creates only one reversal');
select is(public.doctor_practice_money_state(pg_temp.id(21),pg_temp.id(31),pg_temp.value('charge1','charge_id'))#>>'{balance,net_minor}','19900','partial collection less exact refund remains distinct from charge total');
insert into results values('hold',pg_temp.payment('collection','20000',723));
insert into results values('price2',pg_temp.price(pg_temp.value('price1','service_id'),1,'10000',724));
select throws_ok($$select pg_temp.charge(pg_temp.value('price2','id'),1,725,pg_temp.value('charge1','charge_id'),1)$$,'40001','DOCTOR_PRACTICE_ALLOCATED_CHARGE_FLOOR','charge correction cannot erase posted plus pending allocations');
select is(pg_temp.advance('hold',1,'cancel',726)->>'state','failed','unattempted reservation may be explicitly cancelled without financial entry');
insert into results values('price3',pg_temp.price(pg_temp.value('price1','service_id'),2,'20000',727));
insert into results values('charge2',pg_temp.charge(pg_temp.value('price3','id'),1,728,pg_temp.value('charge1','charge_id'),1));
select is(public.doctor_practice_billing_record(pg_temp.id(21),pg_temp.id(31),'charge',pg_temp.value('charge1','id'))->>'amount_minor','149500','financial correction preserves original issued amount');
select throws_ok($$select pg_temp.payment('collection','1',729)$$,'40001','DOCTOR_BILLING_VERSION_CONFLICT','stale charge snapshot cannot authorize a new payment');
reset role;
update public.appointments set state='cancelled',version=version+1 where id=pg_temp.id(61);
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select pg_temp.payment('collection','1',730,null,pg_temp.value('charge2','id'))$$,'40001','DOCTOR_PRACTICE_PAYMENT_VISIT_REVIEW','cancelled visit needs review before any new collection');
select is(public.doctor_practice_money_state(pg_temp.id(21),pg_temp.id(31),pg_temp.value('charge1','charge_id'))#>>'{balance,net_minor}','19900','visit cancellation never invents a refund or destroys original collection');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_practice_money_state(pg_temp.id(21),pg_temp.id(31),pg_temp.value('charge1','charge_id'))$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','independent doctor cannot read foreign payment history');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.payment('collection','1',731,null,pg_temp.value('charge2','id'))$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','administrative secretary grants cannot authorize money');
select pg_temp.claim(1);
reset role;
select is((select count(*)::integer from public.doctor_practice_ledger_entries),2,'only accepted reconciled collection and original-linked refund are posted');
select is((select count(*)::integer from public.doctor_practice_payment_allocations),2,'every entry has its exact atomic source allocation');
select is((select count(*)::integer from doctor_private.synthetic_practice_payment_acceptances),4,'lost replies and reconciliation never dispatch an accepted movement twice');
select throws_ok($$update public.doctor_practice_ledger_entries set amount_minor=1$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','paid history cannot be edited');
select throws_ok($$delete from public.doctor_practice_payment_events$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','outcome history cannot be erased');
select throws_ok($$update doctor_private.synthetic_practice_payment_acceptances set outcome='rejected'$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','persisted acceptance cannot be replaced during reconciliation');
select throws_ok($$delete from public.doctor_practice_receipt_counters$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','receipt sequence cannot be reset');
select ok(not has_table_privilege('authenticated','public.doctor_practice_ledger_entries','SELECT'),'raw financial data is private');
select ok(not has_table_privilege('authenticated','doctor_private.synthetic_practice_payment_acceptances','INSERT'),'client cannot forge transport evidence through raw tables');
select ok(not has_function_privilege('service_role','public.doctor_prepare_practice_payment(uuid,uuid,text,uuid,uuid,text,text,uuid)','EXECUTE'),'service facade cannot bypass owner payment authority');
select is((select count(*)::integer from public.doctor_saas_payment_intents),0,'practice collections never settle Doctor SaaS intents');
select is((select count(*)::integer from public.doctor_saas_periods),0,'practice receipts never create subscription authority');
select ok(not exists(select 1 from doctor_private.command_receipts where command_key in(pg_temp.id(704),pg_temp.id(705),pg_temp.id(706),pg_temp.id(707),pg_temp.id(709),pg_temp.id(710),pg_temp.id(716),pg_temp.id(721),pg_temp.id(725),pg_temp.id(729),pg_temp.id(730),pg_temp.id(731))),'denied requests leave no successful command acknowledgement');
set local role authenticated;select pg_temp.claim(1);
insert into results values('expiryRefund',pg_temp.payment('refund','1000',732,(select(value#>>'{entry,id}')::uuid from results where name='posted'),pg_temp.value('charge2','id')));
select lives_ok($$select pg_temp.advance('expiryRefund',1,'dispatch',733,'accepted')$$,'refund acceptance before entitlement expiry is persisted');
reset role;
update public.doctor_edition_policy set mode='administrative_candidate',revision=revision+1,change_reason='Synthetic inactive billing reconciliation';
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select pg_temp.payment('refund','1',734,(select(value#>>'{entry,id}')::uuid from results where name='posted'),pg_temp.value('charge2','id'))$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','inactive entitlement cannot start another movement');
select is(pg_temp.advance('expiryRefund',2,'reconcile',735)->>'state','posted','reconciliation records an existing accepted outcome without starting another movement after expiry');
select is(public.doctor_practice_money_state(pg_temp.id(21),pg_temp.id(31),pg_temp.value('charge1','charge_id'))->>'can_write','false','reconciling historical acceptance never restores subscription write authority');
reset role;
select is((select count(*)::integer from doctor_private.synthetic_practice_payment_acceptances),5,'expiry reconciliation does not send a new payment attempt');
select * from finish();rollback;
